<script setup lang="ts">
import {ref} from 'vue';import {useRestaurant} from '../store';import {labels,money,orderTotal,type Order} from '../domain';
const props=defineProps<{order:Order}>();const s=useRestaurant(),cancel=ref(false),reason=ref('');
const time=(date:string)=>new Date(date).toLocaleTimeString('es-GT',{hour:'2-digit',minute:'2-digit',timeZone:'America/Guatemala'});
</script>
<template><article class="order-card"><header><strong>Pedido #{{order.id.slice(0,4).toUpperCase()}}</strong><span class="pill" :class="order.status">{{labels[order.status]}}</span></header><small class="muted">{{time(order.created)}}</small><div v-for="(line,i) in order.lines" :key="i" class="order-line"><b>{{line.quantity}}×</b><div><strong>{{line.name}}</strong><p v-if="line.instructions" class="instructions">{{line.instructions}}</p><span v-if="line.allergy" class="allergy">⚠ Alerta de alergia</span></div><span>{{money(line.price*line.quantity)}}</span></div><div class="order-total">Total <strong>{{money(orderTotal(order))}}</strong></div>
<div class="order-actions"><button v-if="order.status==='Pending'&&s.canCook" class="primary" @click="s.act(()=>s.transition(order.id,'Preparing'))">Empezar preparación</button><button v-if="order.status==='Preparing'&&s.canCook" class="primary" @click="s.act(()=>s.transition(order.id,'Ready'))">Marcar listo ✓</button><button v-if="order.status==='Ready'&&s.canServe" class="primary" @click="s.act(()=>s.transition(order.id,'Delivered'))">Confirmar entrega</button><button v-if="order.status==='Pending'&&s.canServe" class="text-button" @click="cancel=!cancel">Cancelar</button></div><form v-if="cancel" @submit.prevent="s.act(()=>{s.transition(props.order.id,'Cancelled',reason);cancel=false})"><label>Motivo de cancelación<input v-model="reason" required maxlength="500"/></label><button class="danger">Confirmar cancelación</button></form><p v-if="order.reason" class="muted">Motivo: {{order.reason}}</p></article></template>